sys_script.script:
/**
 * Sync Filter -- before insert/update, order 100.
 *
 * Keeps cmdb_condition_table equal to the table the chosen Class Mapping reads from.
 *
 * The CMDB Condition is a Conditions field dependent on this one: it has no table of its own
 * and cannot render a condition builder until this column holds a table name. The field must
 * also be on the form -- the builder resolves its dependency through g_form, so a dependent
 * field that is not rendered reads back empty and the builder shows "Please select a table".
 *
 * Runs before "Validate Sync Filter Conditions" (order 200) so that validation sees the table
 * this rule just settled on.
 */
(function executeRule(current, previous /*null when async*/ ) {

    var sourceTable = '';
    var classMappingSysId = current.getValue('class_mapping');

    if (!gs.nil(classMappingSysId)) {
        sourceTable = new IllumioSyncRepoUtils().getClassMappingSourceTable(classMappingSysId);
    }

    var currentTable = current.getValue('cmdb_condition_table');
    if (currentTable == sourceTable) {
        return;
    }

    // A condition authored against the old table is meaningless against the new one and would
    // silently query columns that may not exist, so it goes. But only when the table is really
    // CHANGING: on insert, or when the column is simply being filled in for the first time, the
    // condition was authored against the table we are about to write and must be kept.
    if (!current.isNewRecord() && !gs.nil(currentTable)) {
        current.setValue('cmdb_condition', '');
    }

    current.setValue('cmdb_condition_table', sourceTable);

})(current, previous);
